<script setup>
import {ref,computed,watch,onMounted,onUnmounted,nextTick} from 'vue';
import {Boxes,LayoutGrid,Star,History,Image,Type,QrCode,ArrowLeftRight,Coffee,Code2,ShieldCheck,Github,ArrowUpRight,House,Menu,Languages,Sun,Moon,Sparkles,Search,X,ArrowRight,SearchX,Sprout,Heart,ArrowLeft,Info,FlaskConical,RotateCcw,UploadCloud,Play,Copy,Download,Check,ImageDown,FileDiff,Braces,Binary,Clock3,Fingerprint,Palette,Network,Share2} from 'lucide-vue-next';
const icons={Boxes,LayoutGrid,Star,History,Image,Type,QrCode,ArrowLeftRight,Coffee,Code2,ShieldCheck,Github,ArrowUpRight,House,Menu,Languages,Sun,Moon,Sparkles,Search,X,ArrowRight,SearchX,Sprout,Heart,ArrowLeft,Info,FlaskConical,RotateCcw,UploadCloud,Play,Copy,Download,Check,ImageDown,FileDiff,Braces,Binary,Clock3,Fingerprint,Palette,Network,Share2};
import QRCode from 'qrcode';
const publicFile=name=>import.meta.env.BASE_URL+name;
import FileTool from './FileTool.vue';
import JsonTree from './JsonTree.vue';
import DOMPurify from 'dompurify';
import {categories,tools,searchTools,popularIds,recommendations} from './catalog';
import {runTool,compareText,prepareAdvanced} from './core';
import {readPreference as read} from './storage';
import {tasks,unsupportedDocumentQuery} from './tasks';
import {actionLabel,errorMessage,toolLink} from './tool-ux';
const lang=ref(read('tb-lang','zh'));const dark=ref(read('tb-dark',false));const favorites=ref(read('tb-favorites',[]));const recent=ref(read('tb-recent',[]));
const en=computed(()=>lang.value==='en');const tr=(a,b)=>en.value?b:a;
const query=ref(''),category=ref('all'),view=ref('all'),active=ref(null),input=ref(''),second=ref(''),output=ref(''),mode=ref('encode'),error=ref(''),toast=ref(''),search=ref(null),menu=ref(false);
const NativeImage=window.Image;
const imageFile=ref(null),source=ref(''),imageResult=ref(''),quality=ref(80),resultBytes=ref(0),busy=ref(false),fileInput=ref(null),legal=ref(false);
const resultReady=ref(false),processing=ref(false),resultPanel=ref(null),menuButton=ref(null);
let toastTimer;let task=0;
const chosen=computed(()=>tools.find(t=>t.id===active.value));
const options=ref({});
const isQR=computed(()=>['qr','wifi'].includes(active.value));
const discover=computed(()=>!query.value&&view.value==='all'&&category.value==='all');
const popularTools=popularIds.map(id=>tools.find(t=>t.id===id));
const emptyTitle=computed(()=>query.value?tr('还没找到合适的工具','No matching tool yet'):view.value==='favorites'?tr('把常用工具放在这里','Keep your go-to tools here'):view.value==='recent'?tr('从第一个小任务开始','Start with a small task'):tr('这里暂时没有工具','No tools here yet'));
const emptyText=computed(()=>query.value?unsupportedDocumentQuery(query.value)?tr('目前支持图片压缩、文字处理和 JSON/YAML/CSV 数据转换，支持 PDF 合并与页面提取，尚不支持 PDF、Word 或 Excel 文件互转。','We support image compression, text and JSON/YAML/CSV data. PDF, Word and Excel file conversion is not available.'):tr('试试描述你想完成的事，比如“让照片小一点”或“清理重复名单”。','Try describing a task, such as “make my image smaller” or “clean duplicate text”.'):view.value==='favorites'?tr('点击工具卡片右上角的星星，下次就能直接找到它。','Use the star on a tool card to save it for next time.'):tr('打开一个工具后，它会出现在最近使用中；这里只记录工具名称，不保存输入内容。','Open a tool to find it here next time. History stores tool names, never your input.'));
function chooseTask(t){if(t.primary){open(t.primary);return;}category.value='all';view.value='all';query.value=t.label[en.value?1:0];}
function searchEverywhere(){category.value='all';view.value='all';}
const groups=computed(()=>discover.value?categories.slice(1).map(c=>({id:c[0],title:c[en.value?2:1],icon:c[3],list:visible.value.filter(t=>t.cat===c[0])})).filter(g=>g.list.length):[{id:'results',title:'',list:visible.value}]);
const previewDocument=computed(()=>`<meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; form-action 'none'; base-uri 'none'"><style>body{font:16px/1.7 system-ui;overflow-wrap:anywhere;color:${dark.value?'#e5e7eb':'#263045'}}pre{white-space:pre-wrap}table{border-collapse:collapse}td,th{border:1px solid #aaa;padding:6px}</style>`+DOMPurify.sanitize(output.value,{ALLOWED_TAGS:['p','em','strong','del','code','pre','blockquote','h1','h2','h3','h4','h5','h6','ul','ol','li','table','thead','tbody','tr','td','th','hr','br','a','span','div','details','summary','sub','sup'],ALLOWED_ATTR:['title','colspan','rowspan']}));
const svgPreview=computed(()=>active.value==='svg'&&output.value?'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(output.value):'');
watch(active,id=>{if(tools.find(t=>t.id===id)?.expanded)import('./expansion').then(m=>m.prepareExpansion(id)).catch(()=>{});if(tools.find(t=>t.id===id)?.added)prepareAdvanced().catch(()=>{})});
const visible=computed(()=>{const list=searchTools(query.value,category.value,tools.filter(t=>view.value!=='favorites'||favorites.value.includes(t.id))).filter(t=>view.value!=='recent'||recent.value.includes(t.id));return view.value==='recent'&&!query.value?list.sort((a,b)=>recent.value.indexOf(a.id)-recent.value.indexOf(b.id)):list;});
const recentTools=computed(()=>recent.value.map(id=>tools.find(t=>t.id===id)).filter(Boolean).slice(0,3));
const diff=computed(()=>compareText(input.value,second.value));
const title=computed(()=>view.value==='favorites'?tr('我的收藏','My favorites'):view.value==='recent'?tr('最近使用','Recently used'):category.value==='all'?tr('全部实用工具','Explore all tools'):categories.find(c=>c[0]===category.value)[en.value?2:1]);
watch([lang,dark,favorites,recent],()=>{try{localStorage.setItem('tb-lang',JSON.stringify(lang.value));localStorage.setItem('tb-dark',JSON.stringify(dark.value));localStorage.setItem('tb-favorites',JSON.stringify(favorites.value));localStorage.setItem('tb-recent',JSON.stringify(recent.value));}catch{}document.documentElement.lang=en.value?'en':'zh-CN';document.documentElement.dataset.theme=dark.value?'dark':'light';},{deep:true,immediate:true});
function notify(message){toast.value=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',2600)}
function fav(id){favorites.value=favorites.value.includes(id)?favorites.value.filter(x=>x!==id):[...favorites.value,id]}
function nav(id='all',v='all'){category.value=id;view.value=v;query.value='';menu.value=false;location.hash='';}
function reset(){resultReady.value=false;processing.value=false;task++;input.value='';second.value='';output.value='';error.value='';source.value='';imageResult.value='';imageFile.value=null;resultBytes.value=0;mode.value='encode';quality.value=80;busy.value=false;options.value=Object.fromEntries((chosen.value?.fields??[]).map(f=>[f.key,f.value]));if(fileInput.value)fileInput.value.value='';}
function route(){const id=location.hash.slice(1);active.value=tools.some(t=>t.id===id)?id:null;reset();if(active.value)recent.value=[id,...recent.value.filter(x=>x!==id)].slice(0,12);}
function open(id){location.hash=id;}
function example(){invalidate();input.value=chosen.value.example;if(chosen.value.dual)second.value=chosen.value.secondExample;if(active.value==='wifi')options.value.password='ToolBox12345';if(active.value==='diff')second.value=tr('你好，美好的世界！','Hello, wonderful world!');if(en.value&&active.value==='diff')input.value='Hello, world!';if(en.value&&active.value==='base64')input.value='Hello, ToolBox CN!';if(mode.value==='decode'&&active.value==='base64')input.value='SGVsbG8sIFRvb2xCb3ggQ04h';output.value='';error.value='';}
function clearImageResult(){invalidate();busy.value=false;imageResult.value='';resultBytes.value=0;}
function invalidate(){task++;output.value='';error.value='';resultReady.value=false;processing.value=false;}
async function showResult(){await nextTick();if(window.matchMedia('(max-width: 700px)').matches)resultPanel.value?.scrollIntoView({block:'start',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
async function run(){error.value='';output.value='';resultReady.value=false;processing.value=true;const ticket=++task;try{let data;if(isQR.value){const content=active.value==='wifi'?(await prepareAdvanced()).wifiText(input.value,options.value):input.value;data=await QRCode.toDataURL(content,{width:1024,margin:2,errorCorrectionLevel:'M'});}else data=await runTool(active.value,input.value,mode.value,{...options.value,second:second.value},lang.value);if(ticket===task){output.value=data;resultReady.value=true;showResult();}}catch{if(ticket===task)error.value=errorMessage(active.value,lang.value);}finally{if(ticket===task)processing.value=false;}}
async function shareTool(){try{await navigator.clipboard.writeText(toolLink(location.href,active.value));notify(tr('工具链接已复制，不包含你的输入内容','Tool link copied. It contains none of your input.'));}catch{notify(tr('复制链接失败，请复制浏览器地址栏中的工具网址','Could not copy the link. Copy the tool URL from your address bar.'));}}
async function copy(){try{await navigator.clipboard.writeText(active.value==='diff'?second.value:output.value);notify(tr('已复制到剪贴板','Copied to clipboard'));}catch{notify(tr('复制失败，请手动选择文字复制','Copy failed. Select and copy the text manually.'));}}
function download(){const isImage=active.value==='image'||isQR.value;const data=active.value==='image'?imageResult.value:output.value;if(!data&&!resultReady.value)return;const ext=({'json':'json','json-yaml':'yaml','yaml-json':'json','json-csv':'csv','csv-json':'json','xml':'xml','sql':'sql','markdown':'html','md-preview':'html','md-table':'md','json-xml':'xml','xml-json':'json','json-toml':'toml','toml-json':'json','json-flat':'json','json-view':'json','svg':'svg'})[active.value]??'txt';const url=isImage?data:URL.createObjectURL(new Blob([data],{type:active.value==='svg'?'image/svg+xml;charset=utf-8':'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=active.value==='image'?'toolbox-compressed.jpg':isQR.value?'toolbox-qr.png':'toolbox-'+active.value+'.'+ext;a.click();if(!isImage)setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function loadImage(e){const file=e.target.files?.[0];error.value='';source.value='';imageResult.value='';imageFile.value=null;busy.value=false;const ticket=++task;if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>25*1024*1024){error.value=tr('请选择 25 MB 以内的 JPG、PNG 或 WebP 图片。','Choose a JPG, PNG or WebP image under 25 MB.');return;}try{const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});if(ticket!==task)return;const img=new NativeImage();img.src=data;await img.decode();if(ticket!==task)return;if(img.width*img.height>40000000)throw new Error();imageFile.value=file;source.value=data;}catch{if(ticket===task)error.value=tr('图片无法读取，或超过 4000 万像素。','Cannot read this image, or it exceeds 40 megapixels.');}}
async function compress(){const ticket=++task;busy.value=true;error.value='';try{const img=new NativeImage();img.src=source.value;await img.decode();const c=document.createElement('canvas');c.width=img.naturalWidth;c.height=img.naturalHeight;const ctx=c.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0);const blob=await new Promise(r=>c.toBlob(r,'image/jpeg',quality.value/100));if(!blob)throw new Error();const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob)});if(ticket===task){imageResult.value=data;resultBytes.value=blob.size;showResult();}}catch{if(ticket===task)error.value=tr('压缩失败，请尝试更小的图片。','Compression failed. Try a smaller image.');}finally{if(ticket===task)busy.value=false;}}
function openLegal(){menu.value=false;legal.value=true;}
function closeMenu(){menu.value=false;nextTick(()=>menuButton.value?.focus());}
watch(menu,async shown=>{document.body.style.overflow=shown&&window.matchMedia('(max-width: 700px)').matches?'hidden':'';if(shown){await nextTick();document.querySelector('aside button')?.focus();}});
function resize(){if(innerWidth>700)menu.value=false;}
function key(e){if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();menu.value=false;if(active.value)location.hash='';setTimeout(()=>search.value?.focus(),0)}if(e.key==='Escape'){if(legal.value){legal.value=false;return}if(menu.value){closeMenu();return}}if(e.key==='Tab'&&menu.value&&innerWidth<=700){const root=document.querySelector('aside'),items=[...root.querySelectorAll('a[href],button:not([disabled])')].filter(e=>e.getClientRects().length),first=items[0],last=items.at(-1);if(!root.contains(document.activeElement)||(!e.shiftKey&&document.activeElement===last)){e.preventDefault();first?.focus()}else if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}}}
onMounted(()=>{route();window.addEventListener('hashchange',route);window.addEventListener('keydown',key);window.addEventListener('resize',resize)});onUnmounted(()=>{window.removeEventListener('hashchange',route);window.removeEventListener('keydown',key);window.removeEventListener('resize',resize);document.body.style.overflow='';clearTimeout(toastTimer)});
</script>

<template>
 <div class="app-shell">
  <button v-if="menu" class="nav-backdrop" :aria-label="tr('关闭导航','Close navigation')" @click="closeMenu"/><aside id="tool-navigation" :class="{expanded:menu}" :role="menu?'dialog':undefined" :aria-modal="menu?true:undefined" :aria-label="tr('工具导航','Tool navigation')"><button v-if="menu" class="drawer-close icon-button" :aria-label="tr('关闭菜单','Close menu')" @click="closeMenu"><icons.X :size="20"/></button>
   <a href="#" class="brand" @click="nav()"><span class="brand-mark"><icons.Boxes :size="23"/></span><span>ToolBox <b>CN</b><small>{{tr('你的日常效率工具箱','Your everyday toolkit')}}</small></span></a>
   <div class="nav-caption">{{tr('工作空间','WORKSPACE')}}</div>
   <nav aria-label="Main navigation">
    <button :class="{selected:view==='all'&&category==='all'}" @click="nav()"><icons.LayoutGrid :size="18"/>{{tr('发现工具','Discover tools')}}<span class="count">{{tools.length}}</span></button>
    <button :class="{selected:view==='favorites'}" @click="nav('all','favorites')"><icons.Star :size="18"/>{{tr('我的收藏','My favorites')}}<span class="count">{{favorites.length}}</span></button>
    <button :class="{selected:view==='recent'}" @click="nav('all','recent')"><icons.History :size="18"/>{{tr('最近使用','Recently used')}}</button>
   </nav>
   <div class="nav-caption categories-label">{{tr('按分类探索','EXPLORE CATEGORIES')}}</div>
   <nav><button v-for="c in categories.slice(1)" :key="c[0]" :class="{selected:category===c[0]&&view==='all'}" @click="nav(c[0])"><component :is="icons[c[3]]" :size="18"/>{{c[en?2:1]}}</button></nav>
   <div class="sidebar-bottom"><div class="privacy-card"><icons.ShieldCheck :size="23"/><strong>{{tr('你的数据，只属于你','Your data stays yours')}}</strong><p>{{tr('工具在浏览器本地运行，输入内容无需上传。','Tools run in your browser. Your input stays on your device.')}}</p><span><i/>{{tr('本地处理 · 无需注册','Local processing · No sign-up')}}</span></div><button class="legal-link" @click="openLegal"><icons.Github :size="15"/>{{tr('开源与许可','Open source & license')}}<icons.ArrowUpRight :size="14"/></button></div>
  </aside>
  <div class="main-shell">
   <header><div class="breadcrumb"><button ref="menuButton" class="mobile-toggle icon-button" aria-controls="tool-navigation" :aria-expanded="menu" :aria-label="tr('打开菜单','Open menu')" @click="menu=!menu"><icons.Menu :size="20"/></button><icons.House :size="15"/><span>/</span>{{chosen?chosen.name[en?1:0]:tr('发现工具','Discover tools')}}</div><div class="header-actions"><span class="free-label"><i/>{{tr('免费，无需注册','Free. No sign-up.')}}</span><button class="language" @click="lang=en?'zh':'en'"><icons.Languages :size="16"/>{{en?'简体中文':'English'}}</button><button class="icon-button" :aria-label="tr('切换主题','Toggle theme')" @click="dark=!dark"><component :is="dark?icons.Sun:icons.Moon" :size="18"/></button></div></header>
   <main v-if="!chosen" :inert="menu||undefined">
    <section class="hero"><div class="eyebrow"><span/>{{tr('小工具，大效率','SMALL TOOLS. BIG POSSIBILITIES.')}}</div><h1>{{tr('让日常小事，','Make everyday tasks ')}}<em>{{tr('更简单。','feel effortless.')}}</em></h1><p>{{tr('从图片压缩到文字处理，你需要的实用工具，都在这里。','From images to text, all the little tools you need in one place.')}}</p><div class="searchbox"><icons.Search :size="22"/><input ref="search" v-model="query" :placeholder="tr('想做什么？试试「图片变小」或「生成二维码」','What do you want to do? Try “make my image smaller”')" :aria-label="tr('搜索工具','Search tools')"><button v-if="query" class="icon-button" :aria-label="tr('清空搜索','Clear search')" @click="query=''"><icons.X :size="16"/></button><kbd>Ctrl K</kbd></div><div class="try-search">{{tr('大家都在搜','Try searching')}}<button v-for="s in en?['Compress images','QR code','Word count','JSON','CSV']:['图片压缩','二维码','字数统计','JSON 格式化','表格转换']" :key="s" @click="query=s">{{s}}<icons.ArrowUpRight :size="12"/></button></div><div class="hero-decoration" aria-hidden="true"><icons.Sparkles :size="42"/></div></section>
    <section v-if="discover" class="discovery-section">
     <section class="task-discovery" :aria-label="tr('按任务找工具','Find tools by task')"><strong>{{tr('今天想做什么？','What would you like to do?')}}</strong><div><button v-for="t in tasks" :key="t.id" @click="chooseTask(t)">{{t.label[en?1:0]}}<icons.ArrowUpRight :size="13"/></button></div><small>{{tr('文档对比请复制文字；也可合并 PDF、提取页面，或转换图片与数据格式。','Paste document text to compare it. Merge PDFs, extract pages, or convert images and data formats.')}}</small></section>
     <div class="section-heading"><h2>{{tr('热门常用','Popular essentials')}}</h2><span class="section-note">{{tr('按日常需求精选','Curated for common tasks')}}</span></div>
     <div class="popular-grid"><a v-for="t in popularTools" :key="t.id" :href="'#'+t.id"><span class="tool-icon" :class="t.color"><component :is="icons[t.icon]" :size="20"/></span><strong>{{t.name[en?1:0]}}</strong><icons.ArrowUpRight :size="14"/></a></div>
     <div class="recommendation-grid"><section v-for="(r,i) in recommendations" :key="i"><div class="recommendation-heading"><component :is="[icons.Type,icons.Code2,icons.Palette][i]" :size="18"/><strong>{{r.name[en?1:0]}}</strong></div><p>{{r.desc[en?1:0]}}</p><div class="recommendation-links"><a v-for="id in r.ids" :key="id" :href="'#'+id">{{tools.find(t=>t.id===id).name[en?1:0]}}<icons.ArrowUpRight :size="11"/></a></div></section></div>

    </section>
    <section v-if="recentTools.length&&!query&&view==='all'&&category==='all'" class="recent-section"><div class="section-heading"><h2><icons.History :size="18"/>{{tr('继续上次的工作','Pick up where you left off')}}</h2><button @click="nav('all','recent')">{{tr('查看全部','View all')}} →</button></div><div class="recent-list"><button v-for="t in recentTools" :key="t.id" @click="open(t.id)"><component :is="icons[t.icon]" :size="19"/><span>{{t.name[en?1:0]}}</span><icons.ArrowRight :size="15"/></button></div></section>
    <section class="tools-section"><div class="section-heading"><h2>{{query?tr('搜索结果','Search results'):title}}<span class="small-tag">{{visible.length}} {{tr('个工具','tools')}}</span></h2><span class="section-note">{{tr('少一点繁琐，多一点专注','Less busywork. More flow.')}}</span></div><div class="category-tabs" role="group" :aria-label="tr('工具分类','Tool categories')"><button v-for="c in categories" :key="c[0]" :class="{active:category===c[0]}" @click="category=c[0]"><component :is="icons[c[3]]" :size="15"/>{{c[en?2:1]}}</button></div>
     <section v-for="group in groups" :key="group.id" class="category-group"><div v-if="group.title" class="category-heading"><h3><component :is="icons[group.icon]" :size="17"/>{{group.title}}<span>{{group.list.length}}</span></h3><button @click="nav(group.id)">{{tr('查看分类','View category')}} →</button></div><div class="tool-grid"><article v-for="t in group.list" :key="t.id" class="tool-card"><div class="card-top"><span class="tool-icon" :class="t.color"><component :is="icons[t.icon]" :size="24"/></span><span v-if="['image','qr','json'].includes(t.id)" class="popular">{{tr('热门','Popular')}}</span><button class="favorite icon-button" :class="{saved:favorites.includes(t.id)}" :aria-label="favorites.includes(t.id)?tr('取消收藏','Remove favorite'):tr('收藏工具','Favorite tool')" :aria-pressed="favorites.includes(t.id)" @click="fav(t.id)"><icons.Star :size="17"/></button></div><a :href="'#'+t.id" class="card-link"><h3>{{t.name[en?1:0]}}</h3><p>{{t.desc[en?1:0]}}</p><div class="card-footer"><span v-if="t.localVerified"><icons.ShieldCheck :size="12"/>{{tr('本地处理','On-device')}}</span><icons.ArrowUpRight :size="18"/></div></a></article></div></section>
     <div v-if="!visible.length" class="empty"><icons.SearchX :size="36"/><h3>{{emptyTitle}}</h3><p>{{emptyText}}</p><button v-if="query&&(category!=='all'||view!=='all')" class="primary search-all" @click="searchEverywhere">{{tr('搜索全部工具','Search all tools')}}</button><button class="primary" @click="nav()">{{tr('查看全部工具','Browse all tools')}}</button></div>
    </section>
    <section class="bottom-banner"><span class="banner-icon"><icons.Sprout :size="25"/></span><div><h3>{{tr('好用的工具，应该触手可及。','Useful tools should be within everyone’s reach.')}}</h3><p>{{tr('免费使用，无需登录。把时间留给真正重要的事。','Always free, with no account needed. Save your time for what matters.')}}</p></div><span class="banner-pill">{{tr('为每个人而造','Made for everyone')}}<icons.Heart :size="14"/></span></section>
    <footer><span>© 2026 ToolBox CN</span><span>{{tr('基于 IT-Tools 构建 · GPL-3.0','Built on IT-Tools · GPL-3.0')}}<button @click="openLegal">{{tr('开源与许可','Source & license')}}</button></span></footer>
   </main>
   <main v-else class="workspace" :inert="menu||undefined"><button class="back" @click="nav()"><icons.ArrowLeft :size="16"/>{{tr('返回工具箱','Back to tools')}}</button><div class="workspace-heading"><span class="tool-icon" :class="chosen.color"><component :is="icons[chosen.icon]" :size="26"/></span><div><h1>{{chosen.name[en?1:0]}}</h1><p>{{chosen.desc[en?1:0]}}</p></div><button class="share-button" :aria-label="tr('分享工具','Share tool')" @click="shareTool"><icons.Share2 :size="17"/><span>{{tr('分享工具','Share tool')}}</span></button><button class="icon-button favorite" :aria-pressed="favorites.includes(active)" :class="{saved:favorites.includes(active)}" :aria-label="tr('收藏工具','Favorite tool')" @click="fav(active)"><icons.Star :size="20"/></button></div><div v-if="chosen.localVerified" class="local-badge"><icons.ShieldCheck :size="15"/>{{tr('已验证：本地处理，输入内容不会上传','Verified: on-device processing. Your input is never uploaded.')}}</div><details class="privacy-details"><summary>{{tr('数据如何处理？','How is my data handled?')}}</summary><p>{{tr('打开网页和工具代码需要联网，但输入内容在你的浏览器中处理，不会上传。离开工具或刷新后不会保留输入。收藏和最近使用仅保存工具名称；分享链接也不包含输入内容。','Loading the page and tool code needs a connection, but processing happens in your browser. Inputs are not uploaded or retained after leaving or refreshing. Favorites and history store tool names only, and shared links contain no input.')}}</p></details><div class="instructions"><icons.Info :size="18"/><p>{{chosen.help[en?1:0]}}</p></div>
    <FileTool v-if="chosen.kind==='file'" :key="active" :tool="chosen" :en="en"/><section v-else class="editor-panel"><div class="editor-toolbar"><strong>{{tr('开始使用','Your workspace')}}</strong><div><button v-if="active!=='image'&&active!=='uuid'&&!chosen.noInput" @click="example"><icons.FlaskConical :size="15"/>{{tr('试用示例','Try an example')}}</button><button @click="reset"><icons.RotateCcw :size="15"/>{{tr('重置','Reset')}}</button></div></div>
     <template v-if="active==='image'"><label class="upload-area"><icons.UploadCloud :size="36"/><strong>{{tr('点击选择图片','Click to choose an image')}}</strong><span>JPG / PNG / WebP · {{tr('最大 25 MB','Up to 25 MB')}}</span><input ref="fileInput" class="native-file-input" :aria-label="tr('选择图片文件','Choose image file')" type="file" accept="image/jpeg,image/png,image/webp" @change="loadImage"></label><div v-if="source" class="image-controls"><p>{{imageFile.name}} · {{(imageFile.size/1024).toFixed(1)}} KB</p><label>{{tr('图片质量','Image quality')}}: {{quality}}%<input v-model="quality" @input="clearImageResult" type="range" min="10" max="100"></label><button class="primary" :disabled="busy" @click="compress">{{busy?tr('正在压缩…','Compressing…'):tr('压缩图片','Compress image')}}</button></div><div ref="resultPanel" v-if="source" class="image-previews"><figure><img :src="source" :alt="tr('原始图片','Original image')"><figcaption>{{tr('原图','Original')}}</figcaption></figure><figure v-if="imageResult"><img :src="imageResult" :alt="tr('压缩后图片','Compressed image')"><figcaption>{{(resultBytes/1024).toFixed(1)}} KB · {{resultBytes<imageFile.size?tr('体积减少 ','Size reduced by ')+Math.round((1-resultBytes/imageFile.size)*100)+'%':tr('当前结果比原图更大，建议保留原图或降低质量','Output is larger. Keep the original or lower quality.')}}</figcaption></figure></div></template>
     <template v-else><div v-if="chosen.fields?.length" class="tool-options"><label v-for="field in chosen.fields" :key="field.key">{{field.label[en?1:0]}}<select :data-option="field.key" v-if="field.type==='select'" v-model="options[field.key]" @change="invalidate"><option v-for="choice in field.choices" :key="choice[0]" :value="choice[0]">{{choice[en?2:1]}}</option></select><input v-else :data-option="field.key" v-model="options[field.key]" :type="field.type" :min="field.min" :max="field.max" @input="invalidate"></label></div><div v-if="active==='base64'" class="mode-tabs"><button :class="{active:mode==='encode'}" @click="mode='encode';invalidate()">{{tr('文字 → Base64','Text → Base64')}}</button><button :class="{active:mode==='decode'}" @click="mode='decode';invalidate()">{{tr('Base64 → 文字','Base64 → Text')}}</button></div><div :class="{'dual-editor':active==='diff'||chosen.dual}"><label v-if="active!=='uuid'&&!chosen.noInput" class="input-label">{{active==='diff'||chosen.dual?tr('原始文字','Original text'):(chosen.inputLabel?chosen.inputLabel[en?1:0]:tr('输入内容','Input'))}}<textarea v-model="input" :rows="active==='color'||active==='time'?3:7" :placeholder="tr('把内容粘贴到这里，或点“试用示例”先看看','Paste your content, or try an example to see how it works')" spellcheck="false" @input="invalidate"/></label><label v-if="active==='diff'||chosen.dual" class="input-label">{{tr('修改后的文字','Updated text')}}<textarea v-model="second" rows="7" spellcheck="false" @input="invalidate"/></label></div><label v-if="active==='color'" class="picker-label">{{tr('也可以直接取色','Or pick a color')}}<input type="color" :value="/^#[\da-f]{6}$/i.test(input)?input:'#6366f1'" @input="input=$event.target.value;run()"></label><button v-if="active!=='diff'" class="primary run-button" :disabled="processing" :aria-busy="processing" @click="run"><icons.Play :size="16"/>{{processing?tr('正在处理…','Processing…'):isQR?tr('生成二维码','Generate QR code'):active==='uuid'?tr('生成 UUID','Generate UUID'):actionLabel(active,lang,mode)}}</button><div v-if="active==='diff'" class="diff-output" aria-live="polite"><span v-for="(part,i) in diff" :key="i" :class="{added:part.added,removed:part.removed}">{{part.value}}</span><span v-if="!input&&!second" class="muted">{{tr('输入两段文字，即时查看差异','Enter two texts to see their differences instantly.')}}</span></div><div ref="resultPanel" v-if="resultReady" class="output" aria-live="polite"><img v-if="isQR" :src="output" :alt="tr('生成的二维码','Generated QR code')" class="qr-preview"><template v-else><iframe v-if="active==='md-preview'" title="Markdown preview" class="markdown-preview" sandbox="" referrerpolicy="no-referrer" :srcdoc="previewDocument"/><JsonTree v-if="active==='json-view'" :value="JSON.parse(output)"/><img v-if="svgPreview" :src="svgPreview" :alt="tr('SVG 图片预览','SVG image preview')" class="svg-preview"><label class="input-label">{{tr('处理结果','Result')}}<textarea :value="output" readonly rows="7"/></label></template></div></template>
     <p v-if="resultReady||imageResult" class="result-feedback" role="status"><icons.Check :size="16"/>{{resultReady&&!output?tr('处理完成，结果为空。你仍可复制或下载空结果。','Done. The result is empty; you can still copy or download it.'):active==='image'||isQR?tr('处理完成，可以下载图片。','Done. Your image is ready to download.'):tr('处理完成，可以复制或下载结果。','Done. Your result is ready to copy or download.')}}</p><p v-else-if="!error&&active!=='diff'" class="workspace-hint">{{active==='image'?tr('选择图片后，调整质量并点击“压缩图片”。','Choose an image, adjust quality, then compress it.'):chosen.noInput||active==='uuid'?tr('点击上方生成按钮，即可得到结果。','Use the generate button above to create a result.'):tr('先填入内容或试用示例，再点击主按钮；结果会显示在这里。','Enter content or try an example, then use the primary button. Your result appears here.')}}</p><p v-if="active==='diff'&&(input||second)" class="diff-summary">{{input===second?tr('两段文字相同，没有发现差异。','The texts are identical. No differences found.'):tr('绿色表示新增，红色表示删除；下方可复制修改后的文字。','Green marks additions and red marks removals. Copy the updated text below.')}}</p><p v-if="error" role="alert" class="error">{{error}}</p><div v-if="resultReady||imageResult||(active==='diff'&&(input||second))" class="result-actions"><button v-if="active!=='image'&&!isQR" @click="copy"><icons.Copy :size="16"/>{{tr('复制结果','Copy result')}}</button><button v-if="active!=='diff'" @click="download"><icons.Download :size="16"/>{{tr('下载结果','Download result')}}</button></div>
    </section><p class="workspace-note">{{tr('输入内容仅保留在当前页面；收藏和使用记录保存在此浏览器中。','Inputs stay in this page only. Favorites and tool history are saved in this browser.')}}</p>
   </main>
  </div>
  <div v-if="toast" class="toast" role="status"><icons.Check :size="17"/>{{toast}}</div>
  <div v-if="legal" class="modal-backdrop" @click.self="legal=false"><section role="dialog" aria-modal="true" :aria-label="tr('开源与许可','Open source & license')" class="legal-modal"><button class="icon-button close-modal" :aria-label="tr('关闭','Close')" @click="legal=false"><icons.X :size="20"/></button><h2>{{tr('开源与许可','Open source & license')}}</h2><p>ToolBox CN · GPL-3.0-only</p><p>IT-Tools © Corentin Thomasset & contributors. Based on the sharevb fork. ToolBox CN modifications © 2026 ToolBox CN contributors.</p><p>{{tr('本软件不提供任何担保。你可以按 GPL-3.0 条款使用、修改及再分发本软件。','This software comes with no warranty. You may use, modify and redistribute it under GPL-3.0.')}}</p><p><a :href="publicFile('LICENSE')" target="_blank">GPL-3.0</a> · <a :href="publicFile('source.zip')">{{tr('下载完整对应源码','Download corresponding source')}}</a> · <a href="https://github.com/sharevb/it-tools" target="_blank" rel="noreferrer">IT-Tools</a></p><p>{{tr('工具逻辑复用 IT-Tools Base64 模块及 qrcode、uuid、colord 等开源库；新界面及搜索由 ToolBox CN 开发。','Reuses the IT-Tools Base64 module and open-source qrcode, uuid and colord libraries. Interface and search developed for ToolBox CN.')}}</p></section></div>
 </div>
</template>


